{
  "name": "PrepAI",
  "description": "An AI-powered web application for students in India preparing for competitive exams like IIT JEE, NEET, and board exams. It features a Q-Bank generator, AI doubt solver, study material generator, and performance analytics."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';

// Import Pages
import Dashboard from './pages/Dashboard';
import QBankGenerator from './pages/QBankGenerator';
import StudyMaterials from './pages/StudyMaterials';
import DoubtSolver from './pages/DoubtSolver';
import Analytics from './pages/Analytics';
import Profile from './pages/Profile';
import Admin from './pages/Admin';

// Import Auth Components
import Login from './components/auth/Login';
import Signup from './components/auth/Signup';
import PasswordReset from './components/auth/PasswordReset';

// Import Layout
import MainLayout from './components/layout/MainLayout';
import { User } from './types';

const App: React.FC = () => {
    // A simple mock for auth state. In a real app, use Context or a state management library.
    const [user, setUser] = useState<User | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Mock checking for a logged-in user from localStorage
        const storedUser = localStorage.getItem('prep-ai-user');
        if (storedUser) {
            setUser(JSON.parse(storedUser));
        }
        setLoading(false);
    }, []);

    const handleLogin = (loggedInUser: User) => {
        localStorage.setItem('prep-ai-user', JSON.stringify(loggedInUser));
        setUser(loggedInUser);
    };

    const handleLogout = () => {
        localStorage.removeItem('prep-ai-user');
        setUser(null);
    };

    if (loading) {
        return <div className="flex items-center justify-center h-screen">Loading...</div>;
    }

    return (
        <HashRouter>
            <AppRoutes user={user} onLogin={handleLogin} onLogout={handleLogout} />
        </HashRouter>
    );
};

interface AppRoutesProps {
    user: User | null;
    onLogin: (user: User) => void;
    onLogout: () => void;
}

const AppRoutes: React.FC<AppRoutesProps> = ({ user, onLogin, onLogout }) => {
    const location = useLocation();
    const navigate = useNavigate();

    const [studyMaterialContext, setStudyMaterialContext] = useState(null);

    const navigateToStudyMaterials = useCallback((context: any) => {
        setStudyMaterialContext(context);
        navigate('/study-materials');
    }, [navigate]);

    return (
        <Routes>
            {!user ? (
                <>
                    <Route path="/login" element={<Login onLogin={onLogin} />} />
                    <Route path="/signup" element={<Signup onLogin={onLogin} />} />
                    <Route path="/reset-password" element={<PasswordReset />} />
                    <Route path="*" element={<Navigate to="/login" />} />
                </>
            ) : (
                <Route
                    path="/"
                    element={
                        <MainLayout user={user} onLogout={onLogout}>
                            <Routes location={location}>
                                <Route index element={<Navigate to="/dashboard" replace />} />
                                <Route path="/dashboard" element={<Dashboard user={user} />} />
                                <Route path="/q-bank-generator" element={<QBankGenerator navigateToStudyMaterials={navigateToStudyMaterials} />} />
                                <Route path="/study-materials" element={<StudyMaterials initialContext={studyMaterialContext} />} />
                                <Route path="/doubt-solver" element={<DoubtSolver />} />
                                <Route path="/analytics" element={<Analytics />} />
                                <Route path="/profile" element={<Profile user={user} />} />
                                {user.isAdmin && <Route path="/admin" element={<Admin />} />}
                                <Route path="*" element={<Navigate to="/dashboard" />} />
                            </Routes>
                        </MainLayout>
                    }
                >
                    <Route path="dashboard" element={<Dashboard user={user} />} />
                    <Route path="q-bank-generator" element={<QBankGenerator navigateToStudyMaterials={navigateToStudyMaterials} />} />
                    <Route path="study-materials" element={<StudyMaterials initialContext={studyMaterialContext} />} />
                    <Route path="doubt-solver" element={<DoubtSolver />} />
                    <Route path="analytics" element={<Analytics />} />
                    <Route path="profile" element={<Profile user={user}/>} />
                    {user.isAdmin && <Route path="admin" element={<Admin />} />}
                    <Route path="*" element={<Navigate to="/dashboard" />} />
                </Route>
            )}
        </Routes>
    );
};

export default App;

export interface User {
  name: string;
  email: string;
  isAdmin: boolean;
  targetExam?: string;
  currentClass?: string;
  subjects?: string[];
}

export interface Syllabus {
  [exam: string]: {
    [subject: string]: {
      [chapter: string]: string[];
    };
  };
}

export interface Question {
  id: string;
  questionText: string;
  type: 'MCQ' | 'FillInTheBlank' | 'TrueFalse' | 'ShortAnswer';
  options?: string[];
  correctAnswer: string;
  explanation: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
  topic: string;
}

export interface PriorityTopic {
    topic: string;
    priority: number;
    reason: string;
}

export interface ChatMessage {
  sender: 'user' | 'ai';
  text: string;
}

import { GoogleGenAI, GenerateContentResponse, Chat, Type } from "@google/genai";

// Ensure the API key is available. In a real app, this would be handled more robustly.
const API_KEY = process.env.API_KEY;
if (!API_KEY) {
  throw new Error("API_KEY environment variable not set.");
}
const ai = new GoogleGenAI({ apiKey: API_KEY });

const qBankModel = 'gemini-3-pro-preview';
const studyNotesModel = 'gemini-3-flash-preview';
const chatModel = 'gemini-3-flash-preview';

export const generateQuestionsAndTopics = async (exam: string, subject: string, topic: string, numQuestions: number): Promise<{ questions: any[]; priorityTopics: any[] }> => {
  const prompt = `
    You are an expert content creator for Indian competitive exams. Your task is to generate high-quality questions and a prioritized list of important topics.

    **Instructions:**
    1.  **Generate Questions:** Create ${numQuestions} mixed-type questions (MCQ, Fill in the Blanks, True/False) for the topic "${topic}" under the subject "${subject}" for the "${exam}" exam.
    2.  **Prioritize Topics:** Analyze the entire syllabus for the subject "${subject}" for the "${exam}" exam and provide a prioritized list of the top 5 most important topics. For each topic, give a priority score (1-5, 5 being highest) and a brief reason for its importance (e.g., "High weightage in past papers").

    **Output Format:**
    Return a single JSON object. Do not include any markdown formatting like \`\`\`json.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: qBankModel,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    questions: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                questionText: { type: Type.STRING },
                                type: { type: Type.STRING, enum: ['MCQ', 'FillInTheBlank', 'TrueFalse', 'ShortAnswer'] },
                                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                                correctAnswer: { type: Type.STRING },
                                explanation: { type: Type.STRING },
                                difficulty: { type: Type.STRING, enum: ['Easy', 'Medium', 'Hard'] },
                                topic: { type: Type.STRING },
                            },
                        },
                    },
                    priorityTopics: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                topic: { type: Type.STRING },
                                priority: { type: Type.NUMBER },
                                reason: { type: Type.STRING },
                            },
                        },
                    },
                },
            },
        },
    });

    const jsonText = response.text.trim();
    const data = JSON.parse(jsonText);
    return data;
  } catch (error) {
    console.error("Error generating questions and topics:", error);
    throw new Error("Failed to generate content from Gemini API.");
  }
};


export const suggestVideo = async (topic: string, exam: string): Promise<string> => {
    const prompt = `Find a single, high-quality, and highly relevant YouTube video URL for a student preparing for the ${exam} exam on the topic: "${topic}". The video should be from a reputable educational channel. Return only the full YouTube URL and nothing else.`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        return response.text;
    } catch (error) {
        console.error("Error suggesting video:", error);
        throw new Error("Failed to suggest a video.");
    }
};

export const generateStudyNotes = async (exam: string, subject: string, topic: string): Promise<string> => {
    const prompt = `
        Generate comprehensive, well-structured, and easy-to-understand study notes for a student preparing for the "${exam}" exam.
        Topic: "${topic}"
        Subject: "${subject}"

        The notes should:
        - Be in Markdown format.
        - Cover all key concepts clearly.
        - Use headings, lists, and bold text for structure.
        - Include special markers for emphasis:
            - **[Key Concept]** for fundamental ideas.
            - **[Memorize this formula]** for important formulas.
            - **[Pro Tip]** for helpful exam-taking strategies or shortcuts.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        return response.text;
    } catch (error) {
        console.error("Error generating study notes:", error);
        throw new Error("Failed to generate study notes.");
    }
};

export const createDoubtSolverChat = (): Chat => {
    const systemInstruction = `You are PrepAI, a super friendly, cheerful, and creative AI tutor for Indian students preparing for competitive exams like IIT JEE, NEET, and board exams. Your goal is to make learning fun and accessible.

    **Your Persona:**
    - **Tone:** Always use a positive, encouraging, and slightly informal tone.
    - **Emojis:** Use emojis generously to add personality and visual cues (e.g., 🧠, ✨, 👍, 🚀, 🤔, ✅).
    - **Formatting:** Use markdown (bold, italics, lists, code blocks for formulas/code) to make explanations clear and engaging.
    - **Engagement:** Ask clarifying questions to better understand the student's doubt.

    **CRITICAL RULE: SYLLABUS BOUNDARY**
    You MUST ONLY answer questions related to the syllabus of:
    - **IIT JEE:** Physics, Chemistry, Maths
    - **NEET:** Physics, Chemistry, Biology
    - **Indian Board Exams (CBSE/ICSE):** Classes 10-12 subjects (Physics, Chemistry, Maths, Biology).

    If a student asks a question outside this scope (e.g., about history, geography, general knowledge, politics, or personal opinions), you MUST politely decline to answer the academic part. Instead, you MUST pivot to sharing a fun, unrelated science or math fact.

    **Example of Handling Out-of-Scope Question:**
    *Student:* "Who was the first Prime Minister of India?"
    *You:* "Oops! 😅 That's a great question, but it's a little outside my specialized circuits! I'm laser-focused on helping you ace Physics, Chemistry, Math, and Biology. But hey, speaking of amazing facts, did you know that the human brain generates about 12-25 watts of electricity? That's enough to power a low-wattage LED light bulb! 💡 How cool is that! Now, shall we get back to those tricky calculus problems? 🚀"
    `;

    return ai.chats.create({
        model: chatModel,
        config: {
            systemInstruction: systemInstruction,
        },
    });
};

