import React, { useState, useEffect, useMemo } from 'react';
import { syllabus } from '../data/syllabus';
import { Question, PriorityTopic } from '../types';
import { generateQuestionsAndTopics } from '../services/geminiService';
import QuestionCard from '../components/ui/QuestionCard';
import Loader from '../components/ui/Loader';
import { FilterIcon, BookOpenIcon, SparklesIcon } from '../components/icons/Icons';

interface QBankGeneratorProps {
    navigateToStudyMaterials: (context: any) => void;
}

const QBankGenerator: React.FC<QBankGeneratorProps> = ({ navigateToStudyMaterials }) => {
    const [exam, setExam] = useState(Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState('');
    const [chapter, setChapter] = useState('');
    const [topic, setTopic] = useState('');
    const [numQuestions, setNumQuestions] = useState(5);

    const [subjects, setSubjects] = useState<string[]>([]);
    const [chapters, setChapters] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);

    const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
    const [priorityTopics, setPriorityTopics] = useState<PriorityTopic[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    // Filters
    const [difficultyFilter, setDifficultyFilter] = useState('All');
    const [typeFilter, setTypeFilter] = useState('All');

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        setSubject(availableSubjects[0] || '');
    }, [exam]);

    useEffect(() => {
        if (subject) {
            const availableChapters = Object.keys(syllabus[exam]?.[subject] || {});
            setChapters(availableChapters);
            setChapter(availableChapters[0] || '');
        } else {
            setChapters([]);
            setChapter('');
        }
    }, [exam, subject]);

    useEffect(() => {
        if (chapter) {
            const availableTopics = syllabus[exam]?.[subject]?.[chapter] || [];
            setTopics(availableTopics);
            setTopic(availableTopics[0] || '');
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject, chapter]);

    const handleGenerate = async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsLoading(true);
        setError('');
        setGeneratedQuestions([]);
        setPriorityTopics([]);
        try {
            const result = await generateQuestionsAndTopics(exam, subject, topic, numQuestions);
            setGeneratedQuestions(result.questions);
            setPriorityTopics(result.priorityTopics);
        } catch (err) {
            setError('Failed to generate questions. Please try again.');
            console.error(err);
        }
        setIsLoading(false);
    };

    const filteredQuestions = useMemo(() => {
        return generatedQuestions.filter(q => {
            const difficultyMatch = difficultyFilter === 'All' || q.difficulty === difficultyFilter;
            const typeMatch = typeFilter === 'All' || q.type === typeFilter;
            return difficultyMatch && typeMatch;
        });
    }, [generatedQuestions, difficultyFilter, typeFilter]);

    const handleViewNotes = () => {
        if(exam && subject && chapter && topic) {
            navigateToStudyMaterials({ exam, subject, chapter, topic });
        }
    };


    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-md">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">Q-Bank Generator</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Chapter" value={chapter} onChange={e => setChapter(e.target.value)} options={chapters} disabled={!subject} />
                    <SelectControl label="Topic" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!chapter} />
                    <div className="lg:col-span-1">
                        <label className="block text-sm font-medium text-gray-700">Number of Questions</label>
                        <input type="number" value={numQuestions} onChange={e => setNumQuestions(parseInt(e.target.value, 10))} min="1" max="20" className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md" />
                    </div>
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleGenerate} disabled={isLoading} className="flex items-center justify-center bg-primary text-white font-bold py-2 px-6 rounded-lg shadow hover:bg-primary-700 transition-colors disabled:bg-gray-400">
                        {isLoading ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Generate Questions</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isLoading && <div className="text-center p-10"><Loader /></div>}

            {(generatedQuestions.length > 0 || priorityTopics.length > 0) && !isLoading && (
                <div className="flex flex-col lg:flex-row gap-6">
                    <div className="flex-grow space-y-4">
                        <div className="bg-white p-4 rounded-xl shadow-md flex items-center justify-between">
                            <h3 className="text-xl font-bold text-gray-800">Generated Questions ({filteredQuestions.length})</h3>
                            <div className="flex items-center gap-4">
                                <FilterIcon />
                                <SelectControl value={difficultyFilter} onChange={e => setDifficultyFilter(e.target.value)} options={['All', 'Easy', 'Medium', 'Hard']} small />
                                <SelectControl value={typeFilter} onChange={e => setTypeFilter(e.target.value)} options={['All', 'MCQ', 'FillInTheBlank', 'TrueFalse']} small />
                            </div>
                        </div>
                        {filteredQuestions.map((q, index) => <QuestionCard key={`${q.id}-${index}`} question={q} />)}
                    </div>

                    <div className="w-full lg:w-80 flex-shrink-0">
                        <div className="sticky top-6 space-y-4">
                            <div className="bg-white p-6 rounded-xl shadow-md">
                                 <button onClick={handleViewNotes} className="w-full mb-4 flex items-center justify-center bg-green-500 text-white font-bold py-2 px-4 rounded-lg shadow hover:bg-green-600 transition-colors">
                                    <BookOpenIcon/>
                                    <span className="ml-2">View Notes for {topic}</span>
                                </button>
                                <h3 className="text-lg font-bold text-gray-800 mb-3 border-b pb-2">Top Priority Topics</h3>
                                <ul className="space-y-3">
                                    {priorityTopics.map(pt => (
                                        <li key={pt.topic} className="p-3 bg-gray-50 rounded-lg">
                                            <div className="flex justify-between items-center">
                                                <span className="font-semibold text-gray-700">{pt.topic}</span>
                                                <span className={`font-bold text-sm px-2 py-0.5 rounded-full ${pt.priority >= 4 ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                                    Priority: {pt.priority}/5
                                                </span>
                                            </div>
                                            <p className="text-xs text-gray-500 mt-1">{pt.reason}</p>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean, small?: boolean }> = ({ label, value, onChange, options, disabled, small }) => (
    <div>
        {label && <label className="block text-sm font-medium text-gray-700">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className={`mt-1 block w-full pl-3 pr-10 text-base border-gray-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md ${small ? 'py-1' : 'py-2'} disabled:bg-gray-100`}>
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default QBankGenerator;

import React, { useState, useEffect } from 'react';
import { syllabus } from '../data/syllabus';
import { generateStudyNotes } from '../services/geminiService';
import MarkdownRenderer from '../components/ui/MarkdownRenderer';
import Loader from '../components/ui/Loader';
import { SparklesIcon } from '../components/icons/Icons';

interface StudyMaterialsProps {
    initialContext?: {
        exam: string;
        subject: string;
        chapter: string;
        topic: string;
    } | null;
}

const StudyMaterials: React.FC<StudyMaterialsProps> = ({ initialContext }) => {
    const [exam, setExam] = useState(initialContext?.exam || Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState(initialContext?.subject || '');
    const [chapter, setChapter] = useState(initialContext?.chapter || '');
    const [topic, setTopic] = useState(initialContext?.topic || '');

    const [subjects, setSubjects] = useState<string[]>([]);
    const [chapters, setChapters] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);

    const [notes, setNotes] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        if (!initialContext || exam !== initialContext.exam) {
            setSubject(availableSubjects[0] || '');
        }
    }, [exam, initialContext]);

    useEffect(() => {
        if (subject) {
            const availableChapters = Object.keys(syllabus[exam]?.[subject] || {});
            setChapters(availableChapters);
            if (!initialContext || subject !== initialContext.subject) {
                setChapter(availableChapters[0] || '');
            }
        } else {
            setChapters([]);
            setChapter('');
        }
    }, [exam, subject, initialContext]);

    useEffect(() => {
        if (chapter) {
            const availableTopics = syllabus[exam]?.[subject]?.[chapter] || [];
            setTopics(availableTopics);
            if (!initialContext || chapter !== initialContext.chapter) {
                setTopic(availableTopics[0] || '');
            }
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject, chapter, initialContext]);

    useEffect(() => {
        if(initialContext) {
            handleGetNotes();
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [initialContext]);

    const handleGetNotes = async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsLoading(true);
        setError('');
        setNotes('');
        try {
            const result = await generateStudyNotes(exam, subject, topic);
            setNotes(result);
        } catch (err) {
            setError('Failed to generate study notes. Please try again.');
            console.error(err);
        }
        setIsLoading(false);
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-md">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">Study Materials</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Chapter" value={chapter} onChange={e => setChapter(e.target.value)} options={chapters} disabled={!subject} />
                    <SelectControl label="Topic" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!chapter} />
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleGetNotes} disabled={isLoading} className="flex items-center justify-center bg-primary text-white font-bold py-2 px-6 rounded-lg shadow hover:bg-primary-700 transition-colors disabled:bg-gray-400">
                        {isLoading ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Get Notes</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isLoading && (
                <div className="bg-white p-6 rounded-xl shadow-md text-center">
                    <Loader />
                    <p className="mt-4 text-gray-600">Our AI is crafting the perfect notes for you...</p>
                </div>
            )}

            {notes && !isLoading && (
                <div className="bg-white p-6 rounded-xl shadow-md">
                    <h3 className="text-xl font-bold text-gray-800 mb-4 border-b pb-2">Notes for: {topic}</h3>
                    <MarkdownRenderer content={notes} />
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean }> = ({ label, value, onChange, options, disabled }) => (
    <div>
        {label && <label className="block text-sm font-medium text-gray-700">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md disabled:bg-gray-100">
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default StudyMaterials;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Chat, GenerateContentResponse } from "@google/genai";
import { createDoubtSolverChat } from '../services/geminiService';
import { ChatMessage } from '../types';
import MarkdownRenderer from '../components/ui/MarkdownRenderer';
import { SendIcon, SparklesIcon, UserCircleIcon } from '../components/icons/Icons';

const DoubtSolver: React.FC = () => {
    const [chatSession, setChatSession] = useState<Chat | null>(null);
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [userInput, setUserInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement | null>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        // Initialize chat session on component mount
        const session = createDoubtSolverChat();
        setChatSession(session);
        setMessages([
            { sender: 'ai', text: "Hey there! 🚀 I'm PrepAI, your personal AI tutor. Got a tricky question from Physics, Chemistry, Math, or Biology? Ask away, and let's solve it together! ✨" }
        ]);
    }, []);

    useEffect(scrollToBottom, [messages]);

    const sendMessage = useCallback(async () => {
        if (!userInput.trim() || !chatSession || isLoading) return;

        const userMessage: ChatMessage = { sender: 'user', text: userInput };
        setMessages(prev => [...prev, userMessage]);
        setUserInput('');
        setIsLoading(true);

        try {
            const stream = await chatSession.sendMessageStream({ message: userInput });

            let aiResponseText = '';
            setMessages(prev => [...prev, { sender: 'ai', text: '' }]); // Add placeholder for AI response

            for await (const chunk of stream) {
                const c = chunk as GenerateContentResponse;
                aiResponseText += c.text;
                setMessages(prev => {
                    const newMessages = [...prev];
                    newMessages[newMessages.length - 1].text = aiResponseText;
                    return newMessages;
                });
            }
        } catch (error) {
            console.error("Error sending message:", error);
            setMessages(prev => [...prev, { sender: 'ai', text: "Oh no! 😥 Something went wrong on my end. Please try asking again." }]);
        } finally {
            setIsLoading(false);
        }
    }, [userInput, chatSession, isLoading]);

    return (
        <div className="flex flex-col h-full bg-white rounded-xl shadow-md">
            <div className="p-4 border-b">
                <h2 className="text-xl font-bold text-gray-800">AI Doubt Solver</h2>
            </div>
            <div className="flex-1 p-6 overflow-y-auto space-y-6">
                {messages.map((msg, index) => (
                    <div key={index} className={`flex items-start gap-4 ${msg.sender === 'user' ? 'justify-end' : ''}`}>
                        {msg.sender === 'ai' && (
                            <div className="w-10 h-10 flex-shrink-0 bg-primary-500 text-white rounded-full flex items-center justify-center">
                                <SparklesIcon className="w-6 h-6"/>
                            </div>
                        )}
                        <div className={`max-w-xl p-4 rounded-2xl ${msg.sender === 'ai' ? 'bg-gray-100' : 'bg-primary text-white'}`}>
                           <MarkdownRenderer content={msg.text} isChat={true} />
                        </div>
                        {msg.sender === 'user' && (
                             <div className="w-10 h-10 flex-shrink-0 bg-gray-300 text-white rounded-full flex items-center justify-center">
                                <UserCircleIcon className="w-8 h-8"/>
                            </div>
                        )}
                    </div>
                ))}
                {isLoading && (
                    <div className="flex items-start gap-4">
                        <div className="w-10 h-10 flex-shrink-0 bg-primary-500 text-white rounded-full flex items-center justify-center">
                             <SparklesIcon className="w-6 h-6"/>
                        </div>
                        <div className="max-w-xl p-4 rounded-2xl bg-gray-100 flex items-center space-x-2">
                           <span className="h-2 w-2 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                           <span className="h-2 w-2 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                           <span className="h-2 w-2 bg-gray-500 rounded-full animate-bounce"></span>
                        </div>
