import React, { useState, useEffect } from 'react';
import { Question } from '../../types';
import { suggestVideo } from '../../services/geminiService';
import VideoCard from './VideoCard';
import { CheckCircleIcon, XCircleIcon, SparklesIcon, VideoCameraIcon } from '../icons/Icons';

interface QuestionCardProps {
  question: Question;
}

const QuestionCard: React.FC<QuestionCardProps> = ({ question }) => {
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [isRevealed, setIsRevealed] = useState(false);
  const [showPoints, setShowPoints] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isVideoLoading, setIsVideoLoading] = useState(false);
  const [videoError, setVideoError] = useState('');

  const isCorrect = selectedAnswer === question.correctAnswer;

  const handleAnswerSelect = (answer: string) => {
    if (isRevealed) return;
    setSelectedAnswer(answer);
    setIsRevealed(true);
    if (answer === question.correctAnswer) {
      setShowPoints(true);
      setTimeout(() => setShowPoints(false), 1500);
    }
  };

  const handleSuggestVideo = async () => {
    setIsVideoLoading(true);
    setVideoError('');
    setVideoUrl(null);
    try {
        const url = await suggestVideo(question.topic, 'competitive exams');
        // Simple URL validation
        if (url && (url.startsWith('https://www.youtube.com/') || url.startsWith('https://youtu.be/'))) {
            setVideoUrl(url);
        } else {
            setVideoError('AI returned an invalid URL. Please try again.');
        }
    } catch (error) {
        setVideoError('Could not fetch video suggestion.');
    } finally {
        setIsVideoLoading(false);
    }
  }

  const getOptionClass = (option: string) => {
    if (!isRevealed) {
      return 'border-gray-300 hover:bg-gray-100';
    }
    if (option === question.correctAnswer) {
      return 'bg-green-100 border-green-500 text-green-800 font-semibold';
    }
    if (option === selectedAnswer && option !== question.correctAnswer) {
      return 'bg-red-100 border-red-500 text-red-800 font-semibold';
    }
    return 'border-gray-300';
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-md relative overflow-hidden">
      {showPoints && (
        <div className="absolute top-4 right-4 text-green-500 font-bold text-lg animate-ping">+10 PTS</div>
      )}
      <div className="flex justify-between items-start">
        <p className="text-gray-800 mb-4">{question.questionText}</p>
        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
            question.difficulty === 'Easy' ? 'bg-green-100 text-green-800' :
            question.difficulty === 'Medium' ? 'bg-yellow-100 text-yellow-800' :
            'bg-red-100 text-red-800'
        }`}>{question.difficulty}</span>
      </div>

      <div className="space-y-3">
        {question.options && question.options.map((option, index) => (
          <button
            key={index}
            onClick={() => handleAnswerSelect(option)}
            disabled={isRevealed}
            className={`w-full text-left p-3 border rounded-lg transition-colors duration-200 flex items-center justify-between ${getOptionClass(option)}`}
          >
            <span>{option}</span>
            {isRevealed && option === question.correctAnswer && <CheckCircleIcon className="text-green-600" />}
            {isRevealed && option === selectedAnswer && option !== question.correctAnswer && <XCircleIcon className="text-red-600" />}
          </button>
        ))}
      </div>

      {isRevealed && (
        <div className={`mt-4 p-4 rounded-lg ${isCorrect ? 'bg-green-50' : 'bg-red-50'}`}>
          <h4 className="font-bold">{isCorrect ? 'Correct!' : 'Incorrect'}</h4>
          <p className="text-sm mt-1"><strong>Correct Answer:</strong> {question.correctAnswer}</p>
          <p className="text-sm mt-2"><strong>Explanation:</strong> {question.explanation}</p>
        </div>
      )}

      <div className="mt-4 border-t pt-4">
        <button onClick={handleSuggestVideo} disabled={isVideoLoading} className="flex items-center text-sm font-semibold text-primary hover:underline disabled:text-gray-400">
           {isVideoLoading ? <SparklesIcon className="animate-spin mr-2"/> : <VideoCameraIcon className="mr-2"/>}
           {isVideoLoading ? 'Finding Video...' : `Suggest Video for ${question.topic}`}
        </button>
         {videoUrl && <VideoCard url={videoUrl} />}
         {videoError && <p className="text-red-500 text-sm mt-2">{videoError}</p>}
      </div>
    </div>
  );
};

export default QuestionCard;

import React from 'react';

interface VideoCardProps {
  url: string;
}

const VideoCard: React.FC<VideoCardProps> = ({ url }) => {
  const getEmbedUrl = (videoUrl: string) => {
    let videoId;
    if (videoUrl.includes('youtube.com/watch?v=')) {
      videoId = new URL(videoUrl).searchParams.get('v');
    } else if (videoUrl.includes('youtu.be/')) {
      videoId = new URL(videoUrl).pathname.slice(1);
    }
    return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const embedUrl = getEmbedUrl(url);

  if (!embedUrl) {
    return <p className="text-red-500 mt-2">Invalid YouTube URL provided.</p>;
  }

  return (
    <div className="mt-4">
      <div className="aspect-w-16 aspect-h-9">
        <iframe
          src={embedUrl}
          title="YouTube video player"
          frameBorder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
          className="w-full h-full rounded-lg shadow-md"
        ></iframe>
      </div>
    </div>
  );
};

export default VideoCard;

import React from 'react';
import { LightbulbIcon, BookmarkIcon, SparklesIcon as ProTipIcon } from '../icons/Icons';

interface MarkdownRendererProps {
  content: string;
  isChat?: boolean;
}

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, isChat = false }) => {
  const renderContent = () => {
    let processedContent = content;

    // Custom hints styling
    processedContent = processedContent.replace(/\*\*\[Key Concept\]\*\*(.*?)(\n|$)/g, 
        `<div class="my-4 p-4 border-l-4 border-blue-500 bg-blue-50 rounded-r-lg flex items-start"><span class="mr-3 text-blue-500 flex-shrink-0">${LightbulbIcon({}).props.children}</span><div><strong class="text-blue-700">Key Concept</strong><p class="mt-1">$1</p></div></div>`
    );
    processedContent = processedContent.replace(/\*\*\[Memorize this formula\]\*\*(.*?)(\n|$)/g, 
        `<div class="my-4 p-4 border-l-4 border-yellow-500 bg-yellow-50 rounded-r-lg flex items-start"><span class="mr-3 text-yellow-500 flex-shrink-0">${BookmarkIcon({}).props.children}</span><div><strong class="text-yellow-700">Memorize This Formula</strong><p class="mt-1">$1</p></div></div>`
    );
    processedContent = processedContent.replace(/\*\*\[Pro Tip\]\*\*(.*?)(\n|$)/g,
        `<div class="my-4 p-4 border-l-4 border-purple-500 bg-purple-50 rounded-r-lg flex items-start"><span class="mr-3 text-purple-500 flex-shrink-0">${ProTipIcon({}).props.children}</span><div><strong class="text-purple-700">Pro Tip</strong><p class="mt-1">$1</p></div></div>`
    );

    // Standard markdown
    processedContent = processedContent
      .replace(/```([\s\S]*?)```/g, '<pre class="bg-gray-800 text-white p-4 rounded-md my-4 overflow-x-auto"><code>$1</code></pre>')
      .replace(/`([^`]+)`/g, '<code class="bg-gray-200 text-gray-800 px-1 py-0.5 rounded-md">$1</code>')
      .replace(/^\s*### (.*$)/gim, '<h3 class="text-xl font-bold my-4">$1</h3>')
      .replace(/^\s*## (.*$)/gim, '<h2 class="text-2xl font-bold my-5 border-b pb-2">$1</h2>')
      .replace(/^\s*# (.*$)/gim, '<h1 class="text-3xl font-bold my-6 border-b pb-3">$1</h1>')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/^\s*-\s(.*$)/gim, '<li class="ml-6 mb-1 list-disc">$1</li>')
      .replace(/^\s*\d+\.\s(.*$)/gim, '<li class="ml-6 mb-1 list-decimal">$1</li>')
      .replace(/\n/g, '<br />')
      .replace(/<br \/><(li|pre|div|h[1-3])/g, '<$1') // Fix extra breaks before block elements
      .replace(/<br \/>(\s*<br \/>)+/g, '<br />'); // Collapse multiple breaks

    return { __html: processedContent };
  };

  const textClass = isChat ? 'text-inherit' : 'text-gray-700';

  return <div className={`prose max-w-none ${textClass}`} dangerouslySetInnerHTML={renderContent()} />;
};

export default MarkdownRenderer;

