import React from 'react';
import { LightBulbIcon, BookmarkIcon, SparklesIcon as ProTipIcon } from '../icons/Icons';

interface MarkdownRendererProps  {
  content: string;
  isChat?: boolean;
}

const MarkdownRenderer: React.FC <MarkdownRendererProps> = ({ content, isChat = false }) => {
  const renderContent = () =>  {
    let processedContent = content;

    // Custom hints styling
    processedContent = processedContent.replace(/\ *\*\[Key Concept\]\*\*(.*?)(\n|$)/g, 
        `<div class="my -4 p-4 border-l-4 border-blue-500 bg-blue-50 rounded -r-lg flex items-start"><span class="mr-3 text-blue-500 flex-shrink -0">${LightBulbIcon({}).props.children}</span><div><strong class="text-blue-700 ">Key Concept</strong><p class="mt-1">$1</p></div></div>`
    );

    // Styling for Tips
    processedContent = processedContent.replace(/\ *\*\[Tip\]\*\*(.*?)(\n|$)/g, 
        `<div class="my-4 p-4 border-l-4 border-green-500 bg-green-50 rounded-lg flex items-start"><span class="mr-3 text-green-500 flex-shrink-0">${BookmarkIcon({}).props.children}</span><div><strong class="text-green-700">Tip</strong><p class="mt-1">$1</p></div></div>`
    );

    // Styling for Pro Tips
    processedContent = processedContent.replace(/\ *\*\[Pro Tip\]\*\*(.*?)(\n|$)/g,
        `<div class="my-4 p-4 border-l-4 border-yellow-500 bg-yellow-50 rounded-lg flex items-start"><span class="mr-3 text-yellow-500 flex-shrink-0">${ProTipIcon({}).props.children}</span><div><strong class="text-yellow-700">Pro Tip</strong><p class="mt-1">$1</p></div></div>`
    );
    return processedContent;
  };

  if (!content) return null;
  if (isChat) return <div dangerouslySetInnerHTML={{ __html: content }} />;

  return (
    <div className="prose prose-lg dark:prose-invert">
      <div dangerouslySetInnerHTML={{ __html: renderContent() }} />
    </div>
  );
};
export default MarkdownRenderer; 
]]></content>
