                    <div className="ml-3">
                      <p className="text-sm text-slate-700">{notif.message}</p>
                      <p className="text-xs text-slate-400 mt-1">{notif.time}</p>
                    </div>
                  </li>
                ))}
              </ul>
               <div className="p-2 text-center border-t border-slate-200 bg-slate-50">
                <a href="#" className="text-sm font-semibold text-primary hover:underline">View All Notifications</a>
              </div>
            </div>
          )}
        </div>
        <div className="relative">
          <button
            onClick={() => setProfileDropdownOpen(!profileDropdownOpen)}
            className="flex items-center space-x-2 p-2 rounded-lg hover:bg-slate-100"
          >
            <img
              src={`https://i.pravatar.cc/40?u=${user.email}`}
              alt="User Avatar"
              className="w-8 h-8 rounded-full"
            />
            <span className="hidden md:block font-medium text-slate-700">{user.name}</span>
            <ChevronDownIcon />
          </button>
          {profileDropdownOpen && (
            <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-10 border border-slate-200">
              <a href="#/profile" className="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">
                My Profile
              </a>
              <button
                onClick={onLogout}
                className="w-full text-left flex items-center px-4 py-2 text-sm text-red-600 hover:bg-red-50"
              >
                <LogoutIcon/>
                <span className="ml-2">Logout</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;

