import React, { useState, useEffect, useMemo } from 'react';
import { syllabus } from '../data/syllabus';
import { Question, PriorityTopic } from '../types';
import { generateQuestionsAndTopics } from '../services/geminiService';
import QuestionCard from '../components/ui/QuestionCard';
import Loader from '../components/ui/Loader';
import { FilterIcon, BookOpenIcon, SparklesIcon } from '../components/icons/Icons';

interface QBankGeneratorProps {
    navigateToStudyMaterials: (context: any) => void;
}

const QBankGenerator: React.FC<QBankGeneratorProps> = ({ navigateToStudyMaterials }) => {
    const [exam, setExam] = useState(Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState('');
    const [topic, setTopic] = useState('');
    const [numQuestions, setNumQuestions] = useState(5);

    const [subjects, setSubjects] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);

    const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
    const [priorityTopics, setPriorityTopics] = useState<PriorityTopic[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    // Filters
    const [difficultyFilter, setDifficultyFilter] = useState('All');
    const [typeFilter, setTypeFilter] = useState('All');

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        setSubject(availableSubjects[0] || '');
    }, [exam]);

    useEffect(() => {
        if (subject) {
            const availableTopics = syllabus[exam]?.[subject] || [];
            setTopics(availableTopics);
            setTopic(availableTopics[0] || '');
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject]);

    const handleGenerate = async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsLoading(true);
        setError('');
        setGeneratedQuestions([]);
        setPriorityTopics([]);
        try {
            const result = await generateQuestionsAndTopics(exam, subject, topic, numQuestions);
            setGeneratedQuestions(result.questions);
            setPriorityTopics(result.priorityTopics);
        } catch (err) {
            setError('Failed to generate questions. Please try again.');
            console.error(err);
        }
        setIsLoading(false);
    };

    const filteredQuestions = useMemo(() => {
        return generatedQuestions.filter(q => {
            const difficultyMatch = difficultyFilter === 'All' || q.difficulty === difficultyFilter;
            const typeMatch = typeFilter === 'All' || q.type === typeFilter;
            return difficultyMatch && typeMatch;
        });
    }, [generatedQuestions, difficultyFilter, typeFilter]);

    const handleViewNotes = () => {
        if(exam && subject && topic) {
            navigateToStudyMaterials({ exam, subject, topic });
        }
    };


    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
                <h2 className="text-2xl font-bold text-slate-800 mb-4">Q-Bank Generator</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Topic" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!subject} />
                    <div>
                        <label className="block text-sm font-medium text-slate-700">Number of Questions</label>
                        <input type="number" value={numQuestions} onChange={e => setNumQuestions(parseInt(e.target.value, 10))} min="1" className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md" />
                    </div>
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleGenerate} disabled={isLoading} className="flex items-center justify-center bg-accent text-white font-bold py-2 px-6 rounded-lg shadow hover:bg-accent-600 transition-colors disabled:bg-slate-400">
                        {isLoading ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Generate Questions</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isLoading && <div className="text-center p-10"><Loader /></div>}

            {(generatedQuestions.length > 0 || priorityTopics.length > 0) && !isLoading && (
                <div className="flex flex-col lg:flex-row gap-6">
                    <div className="flex-grow space-y-4">
                        <div className="bg-white p-4 rounded-xl shadow-lg border border-slate-200 flex items-center justify-between">
                            <h3 className="text-xl font-bold text-slate-800">Generated Questions ({filteredQuestions.length})</h3>
                            <div className="flex items-center gap-4">
                                <FilterIcon />
                                <SelectControl value={difficultyFilter} onChange={e => setDifficultyFilter(e.target.value)} options={['All', 'Easy', 'Medium', 'Hard']} small />
                                <SelectControl value={typeFilter} onChange={e => setTypeFilter(e.target.value)} options={['All', 'MCQ', 'FillInTheBlank', 'TrueFalse']} small />
                            </div>
                        </div>
                        {filteredQuestions.map((q, index) => <QuestionCard key={`${q.id}-${index}`} question={q} exam={exam} subject={subject} />)}
                    </div>

                    <div className="w-full lg:w-80 flex-shrink-0">
                        <div className="sticky top-6 space-y-4">
                            <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
                                 <button onClick={handleViewNotes} className="w-full mb-4 flex items-center justify-center bg-green-500 text-white font-bold py-2 px-4 rounded-lg shadow hover:bg-green-600 transition-colors">
                                    <BookOpenIcon/>
                                    <span className="ml-2">View Notes for {topic}</span>
                                </button>
                                <h3 className="text-lg font-bold text-slate-800 mb-3 border-b border-slate-200 pb-2">Top Priority Topics</h3>
                                <ul className="space-y-3">
                                    {priorityTopics.map(pt => (
                                        <li key={pt.topic} className="p-3 bg-slate-50 rounded-lg">
                                            <div className="flex justify-between items-center">
                                                <span className="font-semibold text-slate-700">{pt.topic}</span>
                                                <span className={`font-bold text-sm px-2 py-0.5 rounded-full ${pt.priority >= 4 ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                                    Priority: {pt.priority}/5
                                                </span>
                                            </div>
                                            <p className="text-xs text-slate-500 mt-1">{pt.reason}</p>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean, small?: boolean }> = ({ label, value, onChange, options, disabled, small }) => (
    <div>
        {label && <label className="block text-sm font-medium text-slate-700">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className={`mt-1 block w-full pl-3 pr-10 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md ${small ? 'py-1' : 'py-2'} disabled:bg-slate-100`}>
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default QBankGenerator;

import React, { useState } from 'react';
import { Question } from '../../types';
import { suggestVideo, generateNotesForQuestion } from '../../services/geminiService';
import VideoCard from './VideoCard';
import { CheckCircleIcon, XCircleIcon, SparklesIcon, VideoCameraIcon, BookOpenIcon } from '../icons/Icons';
import MarkdownRenderer from './MarkdownRenderer';
import Loader from './Loader';

interface QuestionCardProps {
  question: Question;
  exam: string;
  subject: string;
}

const QuestionCard: React.FC<QuestionCardProps> = ({ question, exam, subject }) => {
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [isRevealed, setIsRevealed] = useState(false);
  const [showPoints, setShowPoints] = useState(false);

  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isVideoLoading, setIsVideoLoading] = useState(false);
  const [videoError, setVideoError] = useState('');

  const [relatedNotes, setRelatedNotes] = useState<string | null>(null);
  const [isNotesLoading, setIsNotesLoading] = useState(false);
  const [notesError, setNotesError] = useState('');

  const isCorrect = selectedAnswer === question.correctAnswer;

  const handleAnswerSelect = (answer: string) => {
    if (isRevealed) return;
    setSelectedAnswer(answer);
    setIsRevealed(true);
    if (answer === question.correctAnswer) {
      setShowPoints(true);
      setTimeout(() => setShowPoints(false), 1500);
    }
  };

  const handleSuggestVideo = async () => {
    setIsVideoLoading(true);
    setVideoError('');
    setVideoUrl(null);
    try {
        const url = await suggestVideo(question.topic, exam);
        if (url && (url.includes('youtube.com/') || url.includes('youtu.be/'))) {
            setVideoUrl(url);
        } else {
            setVideoError('AI returned an invalid URL. Please try again.');
        }
    } catch (error) {
        setVideoError('Could not fetch video suggestion.');
    } finally {
        setIsVideoLoading(false);
    }
  }

  const handleGetNotes = async () => {
    setIsNotesLoading(true);
    setNotesError('');
    setRelatedNotes(null);
    try {
        const notes = await generateNotesForQuestion(question, exam, subject);
        setRelatedNotes(notes);
    } catch (error) {
        setNotesError('Could not fetch related notes.');
    } finally {
        setIsNotesLoading(false);
    }
  };


  const getOptionClass = (option: string) => {
    if (!isRevealed) {
      return 'border-slate-300 hover:bg-slate-100';
    }
    if (option === question.correctAnswer) {
      return 'bg-green-100 border-green-500 text-green-800 font-semibold';
    }
    if (option === selectedAnswer && option !== question.correctAnswer) {
      return 'bg-red-100 border-red-500 text-red-800 font-semibold';
    }
    return 'border-slate-300';
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200 relative overflow-hidden">
      {showPoints && (
        <div className="absolute top-4 right-4 text-accent font-bold text-lg animate-ping">+10 PTS</div>
      )}
      <div className="flex justify-between items-start">
        <p className="text-slate-800 mb-4 leading-relaxed">{question.questionText}</p>
        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
            question.difficulty === 'Easy' ? 'bg-green-100 text-green-800' :
            question.difficulty === 'Medium' ? 'bg-yellow-100 text-yellow-800' :
            'bg-red-100 text-red-800'
        }`}>{question.difficulty}</span>
      </div>

      <div className="space-y-3">
        {question.options && question.options.map((option, index) => (
          <button
            key={index}
            onClick={() => handleAnswerSelect(option)}
            disabled={isRevealed}
            className={`w-full text-left p-3 border rounded-lg transition-colors duration-200 flex items-center justify-between ${getOptionClass(option)}`}
          >
            <span>{option}</span>
            {isRevealed && option === question.correctAnswer && <CheckCircleIcon className="text-green-600" />}
            {isRevealed && option === selectedAnswer && option !== question.correctAnswer && <XCircleIcon className="text-red-600" />}
          </button>
        ))}
      </div>

      {isRevealed && (
        <div className={`mt-4 p-4 rounded-lg ${isCorrect ? 'bg-green-50' : 'bg-red-50'}`}>
          <h4 className="font-bold text-lg">{isCorrect ? 'Correct!' : 'Incorrect'}</h4>
          <p className="text-sm mt-1"><strong>Correct Answer:</strong> {question.correctAnswer}</p>
          <p className="text-sm mt-2"><strong>Explanation:</strong> {question.explanation}</p>
        </div>
      )}

      <div className="mt-4 border-t border-slate-200 pt-4">
        <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
            <button onClick={handleSuggestVideo} disabled={isVideoLoading} className="flex items-center text-sm font-semibold text-primary hover:underline disabled:text-slate-400">
               {isVideoLoading ? <SparklesIcon className="animate-spin mr-2"/> : <VideoCameraIcon className="mr-2"/>}
               {isVideoLoading ? 'Finding Video...' : 'Suggest Video'}
            </button>
             <button onClick={handleGetNotes} disabled={isNotesLoading} className="flex items-center text-sm font-semibold text-green-600 hover:underline disabled:text-slate-400">
               {isNotesLoading ? <SparklesIcon className="animate-spin mr-2"/> : <BookOpenIcon className="mr-2 h-5 w-5"/>}
               {isNotesLoading ? 'Generating...' : 'Concept Notes'}
            </button>
        </div>

        {videoUrl && !isVideoLoading && <VideoCard url={videoUrl} />}
        {videoError && <p className="text-red-500 text-sm mt-2">{videoError}</p>}

        {isNotesLoading && <div className="text-center py-4"><Loader size="sm"/></div>}
        {relatedNotes && !isNotesLoading && (
            <div className="mt-4 p-4 bg-slate-50 rounded-lg border">
                <MarkdownRenderer content={relatedNotes} />
            </div>
        )}
        {notesError && <p className="text-red-500 text-sm mt-2">{notesError}</p>}

      </div>
    </div>
  );
};

export default QuestionCard;

