import React from 'react';
import { LightBulbIcon, BookmarkIcon, SparklesIcon as ProTipIcon } from '../icons/Icons';

interface MarkdownRendererProps {
  content: string;
  isChat?: boolean;
}

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, isChat = false }) => {
  const renderContent = () => {
    let processedContent = content;

    // 1. Scientific Notations and Symbols
    // This block should come BEFORE standard markdown processing to avoid conflicts.
    processedContent = processedContent
      // Superscripts: handles ^{...} and ^...
      .replace(/\^\{([^}]+)\}/g, '<sup>$1</sup>')
      .replace(/\^([a-zA-Z0-9().-]+)/g, '<sup>$1</sup>')
      // Subscripts: handles _{...} and _...
      .replace(/_\{([^}]+)\}/g, '<sub>$1</sub>')
      .replace(/_([a-zA-Z0-9().-]+)/g, '<sub>$1</sub>');

    // Common symbols
    processedContent = processedContent
      .replace(/(\s?)->(\s?)/g, '$1&rarr;$2')   // Arrow right
      .replace(/(\s?)<->(\s?)/g, '$1&harr;$2')  // Arrow both ways
      .replace(/(\s?)>=(\s?)/g, '$1&ge;$2')     // Greater than or equal to
      .replace(/(\s?)<=(\s?)/g, '$1&le;$2');    // Less than or equal to

    // 2. Custom hints styling
    processedContent = processedContent.replace(/\*\*\[Key Concept\]\*\*(.*?)(\n|$)/g, 
        `<div class="my-4 p-4 border-l-4 border-teal-500 bg-teal-50 rounded-r-lg flex items-start"><span class="mr-3 text-teal-500 flex-shrink-0">${LightBulbIcon({}).props.children}</span><div><strong class="text-teal-700">Key Concept</strong><p class="mt-1">$1</p></div></div>`
    );
    processedContent = processedContent.replace(/\*\*\[Memorize this formula\]\*\*(.*?)(\n|$)/g, 
        `<div class="my-4 p-4 border-l-4 border-yellow-500 bg-yellow-50 rounded-r-lg flex items-start"><span class="mr-3 text-yellow-500 flex-shrink-0">${BookmarkIcon({}).props.children}</span><div><strong class="text-yellow-700">Memorize This Formula</strong><p class="mt-1">$1</p></div></div>`
    );
    processedContent = processedContent.replace(/\*\*\[Pro Tip\]\*\*(.*?)(\n|$)/g,
        `<div class="my-4 p-4 border-l-4 border-orange-500 bg-orange-50 rounded-r-lg flex items-start"><span class="mr-3 text-orange-500 flex-shrink-0">${ProTipIcon({}).props.children}</span><div><strong class="text-orange-700">Pro Tip</strong><p class="mt-1">$1</p></div></div>`
    );

    // 3. Standard markdown
    processedContent = processedContent
      .replace(/```([\s\S]*?)```/g, '<pre class="bg-slate-800 text-white p-4 rounded-md my-4 overflow-x-auto"><code>$1</code></pre>')
      .replace(/`([^`]+)`/g, '<code class="bg-slate-200 text-slate-800 px-1 py-0.5 rounded-md">$1</code>')
      .replace(/^\s*### (.*$)/gim, '<h3 class="text-xl font-bold my-4">$1</h3>')
      .replace(/^\s*## (.*$)/gim, '<h2 class="text-2xl font-bold my-5 border-b pb-2">$1</h2>')
      .replace(/^\s*# (.*$)/gim, '<h1 class="text-3xl font-bold my-6 border-b pb-3">$1</h1>')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/^\s*-\s(.*$)/gim, '<li class="ml-6 mb-1 list-disc">$1</li>')
      .replace(/^\s*\d+\.\s(.*$)/gim, '<li class="ml-6 mb-1 list-decimal">$1</li>')
      .replace(/\n/g, '<br />')
      .replace(/<br \/><(li|pre|div|h[1-3])/g, '<$1') // Fix extra breaks before block elements
      .replace(/<br \/>(\s*<br \/>)+/g, '<br />'); // Collapse multiple breaks

    return { __html: processedContent };
  };

  const textClass = isChat ? 'text-inherit' : 'text-slate-700 leading-relaxed';

  return <div className={`prose max-w-none ${textClass}`} dangerouslySetInnerHTML={renderContent()} />;
};

export default MarkdownRenderer;

