import Loader from '../components/ui/Loader';
import { FilterIcon, BookOpenIcon, SparklesIcon } from '../components/icons/Icons';

interface QBankGeneratorProps {
    navigateToStudyMaterials: (context: any) => void;
}

const QBankGenerator: React.FC<QBankGeneratorProps> = ({ navigateToStudyMaterials }) => {
    const [exam, setExam] = useState(Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState('');
    const [topic, setTopic] = useState('');
    const [numQuestions, setNumQuestions] = useState(5);

    const [subjects, setSubjects] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);

    const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
    const [priorityTopics, setPriorityTopics] = useState<PriorityTopic[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    // Filters
    const [difficultyFilter, setDifficultyFilter] = useState('All');
    const [typeFilter, setTypeFilter] = useState('All');

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        setSubject(availableSubjects[0] || '');
    }, [exam]);

    useEffect(() => {
        if (subject) {
            const availableTopics = syllabus[exam]?.[subject] || [];
            setTopics(availableTopics);
            setTopic(availableTopics[0] || '');
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject]);

    const handleGenerate = async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsLoading(true);
        setError('');
        setGeneratedQuestions([]);
        setPriorityTopics([]);
        try {
            const result = await generateQuestionsAndTopics(exam, subject, topic, numQuestions);
            setGeneratedQuestions(result.questions);
            setPriorityTopics(result.priorityTopics);
        } catch (err) {
            setError('Failed to generate questions. Please try again.');
            console.error(err);
        }
        setIsLoading(false);
    };

    const filteredQuestions = useMemo(() => {
        return generatedQuestions.filter(q => {
            const difficultyMatch = difficultyFilter === 'All' || q.difficulty === difficultyFilter;
            const typeMatch = typeFilter === 'All' || q.type === typeFilter;
            return difficultyMatch && typeMatch;
        });
    }, [generatedQuestions, difficultyFilter, typeFilter]);

    const handleViewNotes = () => {
        if(exam && subject && topic) {
            navigateToStudyMaterials({ exam, subject, topic });
        }
    };


    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
                <h2 className="text-2xl font-bold text-slate-800 mb-4">Q-Bank Generator</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Chapter" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!subject} />
                    <div>
                        <label className="block text-sm font-medium text-slate-700">Number of Questions</label>
                        <input type="number" value={numQuestions} onChange={e => setNumQuestions(parseInt(e.target.value, 10))} min="1" className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md" />
                    </div>
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleGenerate} disabled={isLoading} className="flex items-center justify-center bg-accent text-white font-bold py-2 px-6 rounded-lg shadow hover:bg-accent-600 transition-colors disabled:bg-slate-400">
                        {isLoading ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Generate Questions</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isLoading && <div className="text-center p-10"><Loader /></div>}

            {(generatedQuestions.length > 0 || priorityTopics.length > 0) && !isLoading && (
                <div className="flex flex-col lg:flex-row gap-6">
                    <div className="flex-grow space-y-4">
                        <div className="bg-white p-4 rounded-xl shadow-lg border border-slate-200 flex items-center justify-between">
                            <h3 className="text-xl font-bold text-slate-800">Generated Questions ({filteredQuestions.length})</h3>
                            <div className="flex items-center gap-4">
                                <FilterIcon />
                                <SelectControl value={difficultyFilter} onChange={e => setDifficultyFilter(e.target.value)} options={['All', 'Easy', 'Medium', 'Hard']} small />
                                <SelectControl value={typeFilter} onChange={e => setTypeFilter(e.target.value)} options={['All', 'MCQ', 'FillInTheBlank', 'TrueFalse']} small />
                            </div>
                        </div>
                        {filteredQuestions.map((q, index) => <QuestionCard key={`${q.id}-${index}`} question={q} exam={exam} subject={subject} />)}
                    </div>

                    <div className="w-full lg:w-80 flex-shrink-0">
                        <div className="sticky top-6 space-y-4">
                            <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
                                 <button onClick={handleViewNotes} className="w-full mb-4 flex items-center justify-center bg-green-500 text-white font-bold py-2 px-4 rounded-lg shadow hover:bg-green-600 transition-colors">
                                    <BookOpenIcon/>
                                    <span className="ml-2">View Notes for {topic}</span>
                                </button>
                                <h3 className="text-lg font-bold text-slate-800 mb-3 border-b border-slate-200 pb-2">Top Priority Chapters</h3>
                                <ul className="space-y-3">
                                    {priorityTopics.map(pt => (
                                        <li key={pt.topic} className="p-3 bg-slate-50 rounded-lg">
                                            <div className="flex justify-between items-center">
                                                <span className="font-semibold text-slate-700">{pt.topic}</span>
                                                <span className={`font-bold text-sm px-2 py-0.5 rounded-full ${pt.priority >= 4 ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                                    Priority: {pt.priority}/5
                                                </span>
                                            </div>
                                            <p className="text-xs text-slate-500 mt-1">{pt.reason}</p>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean, small?: boolean }> = ({ label, value, onChange, options, disabled, small }) => (
    <div>
        {label && <label className="block text-sm font-medium text-slate-700">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className={`mt-1 block w-full pl-3 pr-10 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md ${small ? 'py-1' : 'py-2'} disabled:bg-slate-100`}>
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default QBankGenerator;

import React, { useState, useEffect } from 'react';
import { syllabus } from '../data/syllabus';
import { generateStudyNotes } from '../services/geminiService';
import MarkdownRenderer from '../components/ui/MarkdownRenderer';
import Loader from '../components/ui/Loader';
import { SparklesIcon } from '../components/icons/Icons';

interface StudyMaterialsProps {
    initialContext?: {
        exam: string;
        subject: string;
        topic: string;
    } | null;
}

const StudyMaterials: React.FC<StudyMaterialsProps> = ({ initialContext }) => {
    const [exam, setExam] = useState(initialContext?.exam || Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState(initialContext?.subject || '');
    const [topic, setTopic] = useState(initialContext?.topic || '');

    const [subjects, setSubjects] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);

    const [notes, setNotes] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        if (!initialContext || exam !== initialContext.exam) {
            setSubject(availableSubjects[0] || '');
        }
    }, [exam, initialContext]);

    useEffect(() => {
        if (subject) {
            const availableTopics = syllabus[exam]?.[subject] || [];
            setTopics(availableTopics);
            if (!initialContext || subject !== initialContext.subject) {
                setTopic(availableTopics[0] || '');
            }
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject, initialContext]);

    useEffect(() => {
        if(initialContext) {
            handleGetNotes();
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [initialContext]);

    const handleGetNotes = async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsLoading(true);
        setError('');
        setNotes('');
        try {
            const result = await generateStudyNotes(exam, subject, topic);
            setNotes(result);
        } catch (err) {
            setError('Failed to generate study notes. Please try again.');
            console.error(err);
        }
        setIsLoading(false);
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
                <h2 className="text-2xl font-bold text-slate-800 mb-4">Study Materials</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Chapter" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!subject} />
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleGetNotes} disabled={isLoading} className="flex items-center justify-center bg-accent text-white font-bold py-2 px-6 rounded-lg shadow hover:bg-accent-600 transition-colors disabled:bg-slate-400">
                        {isLoading ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Get Notes</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isLoading && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200 text-center">
                    <Loader />
                    <p className="mt-4 text-slate-600">Our AI is crafting the perfect notes for you...</p>
                </div>
            )}

            {notes && !isLoading && (
                <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
                    <h3 className="text-xl font-bold text-slate-800 mb-4 border-b border-slate-200 pb-2">Notes for: {topic}</h3>
                    <MarkdownRenderer content={notes} />
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean }> = ({ label, value, onChange, options, disabled }) => (
    <div>
        {label && <label className="block text-sm font-medium text-slate-700">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md disabled:bg-slate-100">
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default StudyMaterials;

import { GoogleGenAI, GenerateContentResponse, Chat, Type, Question } from "@google/genai";
import { syllabus } from "../data/syllabus";

// Ensure the API key is available. In a real app, this would be handled more robustly.
const API_KEY = process.env.API_KEY;
if (!API_KEY) {
  throw new Error("API_KEY environment variable not set.");
}
const ai = new GoogleGenAI({ apiKey: API_KEY });

const qBankModel = 'gemini-3-pro-preview';
const studyNotesModel = 'gemini-3-flash-preview';
const chatModel = 'gemini-3-flash-preview';

export const generateQuestionsAndTopics = async (exam: string, subject: string, topic: string, numQuestions: number): Promise<{ questions: any[]; priorityTopics: any[] }> => {
  const chapterList = syllabus[exam]?.[subject] || [];
  const prompt = `
    You are an expert content creator for Indian competitive exams. Your task is to generate high-quality questions and a prioritized list of important topics based on the provided syllabus.

    **Syllabus for ${subject} - ${exam}:**
    ${chapterList.join(', ')}

    **Instructions:**
    1.  **Generate Questions:** Create **exactly** ${numQuestions} mixed-type questions (MCQ, Fill in the Blanks, True/False) for the chapter "${topic}" under the subject "${subject}" for the "${exam}" exam. The questions should be highly relevant to the specific chapter.
    2.  **Prioritize Chapters:** From the provided syllabus list above, analyze all chapters for the subject "${subject}" and provide a prioritized list of the top 5 most important chapters. For each, give a priority score (1-5, 5 being highest) and a brief reason for its importance (e.g., "High weightage in past papers").
    3.  **Use Notation:** Where necessary, use standard scientific notation for formulas, equations, and units (e.g., \`H_2O\`, \`x^2\`, \`10^{-19} C\`).

    **Output Format:**
    Return a single JSON object. Do not include any markdown formatting like \`\`\`json. The 'questions' array in the JSON **MUST** have exactly ${numQuestions} items.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: qBankModel,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    questions: {
                        type: Type.ARRAY,
                        minItems: numQuestions,
                        maxItems: numQuestions,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                questionText: { type: Type.STRING },
                                type: { type: Type.STRING, enum: ['MCQ', 'FillInTheBlank', 'TrueFalse', 'ShortAnswer'] },
                                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                                correctAnswer: { type: Type.STRING },
                                explanation: { type: Type.STRING },
                                difficulty: { type: Type.STRING, enum: ['Easy', 'Medium', 'Hard'] },
                                topic: { type: Type.STRING },
                            },
                        },
                    },
                    priorityTopics: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                topic: { type: Type.STRING },
                                priority: { type: Type.NUMBER },
                                reason: { type: Type.STRING },
                            },
                        },
                    },
                },
            },
        },
    });

    const jsonText = response.text.trim();
    const data = JSON.parse(jsonText);
    return data;
  } catch (error) {
    console.error("Error generating questions and topics:", error);
    throw new Error("Failed to generate content from Gemini API.");
  }
};


export const suggestVideo = async (topic: string, exam: string): Promise<string> => {
    const prompt = `Find a single, high-quality, and highly relevant YouTube video URL for a student preparing for the ${exam} exam on the topic: "${topic}". The video should be from a reputable educational channel. Return only the full YouTube URL and nothing else.`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        return response.text;
    } catch (error) {
        console.error("Error suggesting video:", error);
        throw new Error("Failed to suggest a video.");
    }
};

export const generateStudyNotes = async (exam: string, subject: string, topic: string): Promise<string> => {
    const prompt = `
        Generate comprehensive, well-structured, and easy-to-understand study notes for a student preparing for the "${exam}" exam.
        Subject: "${subject}"
        Chapter: "${topic}"

        The notes should:
        - Be in Markdown format.
        - Focus specifically on the requested chapter.
        - Cover all key concepts clearly.
        - Use standard scientific notation for formulas and equations (e.g., \`E = mc^2\`, \`H_2O\`).
        - Use headings, lists, and bold text for structure.
        - Include special markers for emphasis:
            - **[Key Concept]** for fundamental ideas.
            - **[Memorize this formula]** for important formulas.
            - **[Pro Tip]** for helpful exam-taking strategies or shortcuts.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        return response.text;
    } catch (error) {
        console.error("Error generating study notes:", error);
        throw new Error("Failed to generate study notes.");
    }
};

export const generateNotesForQuestion = async (question: Question, exam: string, subject: string): Promise<string> => {
    const prompt = `
        A student is preparing for the "${exam}" exam and is working on the subject "${subject}".
        They are currently attempting the following question on the chapter "${question.topic}":

        **Question:** "${question.questionText}"
        ${question.options ? `**Options:** ${question.options.join(', ')}` : ''}
        **Correct Answer:** ${question.correctAnswer}

        Generate concise and clear study notes in Markdown format that explain the key concepts, formulas, and principles required to understand and solve THIS SPECIFIC question.
        Focus only on the direct knowledge needed for this question. Do not explain the entire chapter.
        Use standard scientific notation for any formulas or values (e.g., \`H_2O\`, \`x^2\`).
        Use headings, lists, and bold text. Mark important formulas with **[Memorize this formula]**.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
        });
        return response.text;
    } catch (error) {
        console.error("Error generating notes for question:", error);
        throw new Error("Failed to generate contextual notes.");
    }
};

