export const generateQuestions = async (exam: string, subject: string, topic: string, numQuestions: number): Promise<Question[]> => {
  const prompt = `
    You are an expert content creator for Indian competitive exams.
    **Instructions:**
    1.  Generate **exactly** ${numQuestions} mixed-type questions (MCQ, Fill in the Blanks, True/False) for the chapter "${topic}" under the subject "${subject}" for the "${exam}" exam. The questions should be highly relevant to the specific chapter.
    2.  **Use Notation:** Where necessary, use standard scientific notation for formulas, equations, and units (e.g., \`H_2O\`, \`x^2\`, \`10^{-19} C\`).
    **Output Format:**
    Return a single JSON object with a key "questions" containing an array. Do not include any markdown formatting like \`\`\`json. The 'questions' array **MUST** have exactly ${numQuestions} items.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: qBankModel,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    questions: {
                        type: Type.ARRAY,
                        minItems: numQuestions,
                        maxItems: numQuestions,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                questionText: { type: Type.STRING },
                                type: { type: Type.STRING, enum: ['MCQ', 'FillInTheBlank', 'TrueFalse', 'ShortAnswer'] },
