    // 1. Handle commands like \vec
    processedMath = processedMath.replace(/\\vec\{?([a-zA-Z])\}?/g, '$1\u20d7');

    // 2. Handle \dots
    processedMath = processedMath.replace(/\\dots/g, '…');

    // 3. Greek letters
    const greek: { [key: string]: string } = {
