const BATCH_SIZE = 20; // Max questions per single API call to avoid constraint errors

/**
 * Generates a single batch of questions. This function is called internally by the main generateQuestions orchestrator.
 */
const generateQuestionBatch = async (exam: string, subject: string, topic: string, numQuestions: number): Promise<Question[]> => {
  const prompt = `
    You are an expert content creator for Indian competitive exams.
    **Instructions:**
    1.  Generate **exactly** ${numQuestions} diverse, high-quality, and unique questions (MCQ, Fill in the Blanks, True/False) for the chapter "${topic}" under the subject "${subject}" for the "${exam}" exam.
    2.  Ensure the questions are distinct from each other and cover different aspects of the chapter.
    3.  **Use Notation:** Where necessary, use LaTeX-style syntax within dollar signs for formulas, equations, and units (e.g., $H_2O$, $x^2$, $10^{-19} C$). Do NOT use markdown backticks for math formulas.
    **Output Format:**
    Return a single JSON object with a key "questions" containing an array. Do not include any markdown formatting like \`\`\`json. The 'questions' array **MUST** have exactly ${numQuestions} items.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: qBankModel,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    questions: {
                        type: Type.ARRAY,
                        minItems: numQuestions,
                        maxItems: numQuestions,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                questionText: { type: Type.STRING },
                                type: { type: Type.STRING, enum: ['MCQ', 'FillInTheBlank', 'TrueFalse', 'ShortAnswer'] },
                                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                                correctAnswer: { type: Type.STRING },
                                explanation: { type: Type.STRING },
                                difficulty: { type: Type.STRING, enum: ['Easy', 'Medium', 'Hard'] },
                                topic: { type: Type.STRING },
                            },
                             required: ['id', 'questionText', 'type', 'correctAnswer', 'explanation', 'difficulty', 'topic'],
                        },
                    },
                },
                 required: ['questions'],
            },
        },
    });

    const jsonText = response.text.trim();
    const data = JSON.parse(jsonText);
    return data.questions;
  } catch (error) {
    console.error(`Error generating a batch of ${numQuestions} questions:`, error);
    throw new Error(`Failed to generate a batch of questions from Gemini API.`);
  }
};

/**
 * Orchestrates the generation of questions, breaking large requests into smaller batches to avoid API limits.
 */
export const generateQuestions = async (exam: string, subject: string, topic: string, totalQuestions: number): Promise<Question[]> => {
  if (totalQuestions <= 0) {
    return [];
  }

  const numBatches = Math.ceil(totalQuestions / BATCH_SIZE);
  const promises: Promise<Question[]>[] = [];

  for (let i = 0; i < numBatches; i++) {
    const isLastBatch = i === numBatches - 1;
    const questionsInBatch = isLastBatch 
      ? totalQuestions - (i * BATCH_SIZE) 
      : BATCH_SIZE;

    if (questionsInBatch > 0) {
        promises.push(generateQuestionBatch(exam, subject, topic, questionsInBatch));
    }
  }

  try {
    const results = await Promise.all(promises);
    const allQuestions = results.flat();

    // The model might generate duplicate IDs across batches. Ensure they are unique.
    return allQuestions.map((q, index) => ({
        ...q,
        id: `${q.topic}-${index}`
    }));
  } catch (error) {
    console.error("Error generating question batches:", error);
    throw new Error("Failed to generate content from Gemini API. One of the batches may have failed.");
  }
};


