import React, { useState, useEffect, useMemo } from 'react';
import { syllabus } from '../data/syllabus';
import { Question, PriorityTopic } from '../types';
import { generateQuestions, getPriorityTopics } from '../services/geminiService';
import QuestionCard from '../components/ui/QuestionCard';
import Loader from '../components/ui/Loader';
import { FilterIcon, BookOpenIcon, SparklesIcon } from '../components/icons/Icons';

const QBankGenerator: React.FC = () => {
    const [exam, setExam] = useState(Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState('');
    const [topic, setTopic] = useState('');
    const [numQuestions, setNumQuestions] = useState(5);

    const [subjects, setSubjects] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);

    const [generatedQuestions, setGeneratedQuestions] = useState<Question[]>([]);
    const [priorityTopics, setPriorityTopics] = useState<PriorityTopic[]>([]);
    const [isGeneratingQuestions, setIsGeneratingQuestions] = useState(false);
    const [isLoadingTopics, setIsLoadingTopics] = useState(false);
    const [error, setError] = useState('');

    // Filters
    const [difficultyFilter, setDifficultyFilter] = useState('All');
    const [typeFilter, setTypeFilter] = useState('All');

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        setSubject(availableSubjects[0] || '');
    }, [exam]);

    useEffect(() => {
        if (subject) {
            const availableTopics = syllabus[exam]?.[subject] || [];
            setTopics(availableTopics);
            setTopic(availableTopics[0] || '');
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject]);

    // Fetch priority topics only when exam or subject changes to avoid rate limiting
    useEffect(() => {
        const fetchPriorityTopics = async () => {
            if (exam && subject) {
                setIsLoadingTopics(true);
                setPriorityTopics([]);
                try {
                    const topicsResult = await getPriorityTopics(exam, subject);
                    setPriorityTopics(topicsResult);
                } catch (err) {
                    console.error("Failed to fetch priority topics:", err);
                    // Optionally set an error state for the topics list
                } finally {
                    setIsLoadingTopics(false);
                }
            }
        };
        fetchPriorityTopics();
    }, [exam, subject]);

    const handleGenerate = async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsGeneratingQuestions(true);
        setError('');
        setGeneratedQuestions([]);
        try {
            const questionsResult = await generateQuestions(exam, subject, topic, numQuestions);
            setGeneratedQuestions(questionsResult);
        } catch (err) {
            setError('Failed to generate content. Please try again.');
            console.error(err);
        } finally {
            setIsGeneratingQuestions(false);
        }
    };

    const filteredQuestions = useMemo(() => {
        return generatedQuestions.filter(q => {
            const difficultyMatch = difficultyFilter === 'All' || q.difficulty === difficultyFilter;
            const typeMatch = typeFilter === 'All' || q.type === typeFilter;
            return difficultyMatch && typeMatch;
        });
    }, [generatedQuestions, difficultyFilter, typeFilter]);

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-md border border-slate-200">
                <h2 className="text-2xl font-bold font-serif text-charcoal mb-4">Q-Bank Generator</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Chapter" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!subject} />
                    <div>
                        <label className="block text-sm font-medium text-charcoal">Number of Questions</label>
                        <input
                            type="number"
                            value={numQuestions}
                            onChange={e => {
                                const val = parseInt(e.target.value, 10) || 1;
                                if (val < 1) setNumQuestions(1);
                                else setNumQuestions(val);
                            }}
                            min="1"
                            className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md"
                        />
                    </div>
                </div>
                <div className="mt-6 flex justify-end">
                    <button onClick={handleGenerate} disabled={isGeneratingQuestions} className="flex items-center justify-center bg-accent text-white font-bold py-2 px-6 rounded-lg shadow-sm hover:bg-accent-600 transition-colors disabled:bg-slate-400">
                        {isGeneratingQuestions ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Generate Questions</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isGeneratingQuestions && <div className="text-center p-10"><Loader /></div>}

            {(generatedQuestions.length > 0 || priorityTopics.length > 0 || isLoadingTopics) && !isGeneratingQuestions && (
                <div className="flex flex-col lg:flex-row gap-6">
                    <div className="flex-grow space-y-4">
                        <div className="bg-white p-4 rounded-xl shadow-md border border-slate-200 flex items-center justify-between">
                            <h3 className="text-xl font-bold font-serif text-charcoal">Generated Questions ({filteredQuestions.length})</h3>
                            <div className="flex items-center gap-4">
                                <FilterIcon />
                                <SelectControl value={difficultyFilter} onChange={e => setDifficultyFilter(e.target.value)} options={['All', 'Easy', 'Medium', 'Hard']} small />
                                <SelectControl value={typeFilter} onChange={e => setTypeFilter(e.target.value)} options={['All', 'MCQ', 'FillInTheBlank', 'TrueFalse']} small />
                            </div>
                        </div>
                        {filteredQuestions.map((q, index) => <QuestionCard key={`${q.id}-${index}`} question={q} exam={exam} subject={subject} questionNumber={index + 1} />)}
                    </div>

                    <div className="w-full lg:w-80 flex-shrink-0">
                        <div className="sticky top-6 space-y-4">
                            <div className="bg-white p-6 rounded-xl shadow-md border border-slate-200">
                                <h3 className="text-lg font-bold font-serif text-charcoal mb-3 border-b border-slate-200 pb-2">Top Priority Chapters</h3>
                                {isLoadingTopics ? (
                                    <div className="flex justify-center items-center h-40">
                                        <Loader />
                                    </div>
                                ) : (
                                    <ul className="space-y-3">
                                        {priorityTopics.map(pt => (
                                            <li key={pt.topic} className="p-3 bg-slate-50 rounded-lg border border-slate-200">
                                                <div className="flex justify-between items-center">
                                                    <span className="font-semibold text-charcoal">{pt.topic}</span>
                                                    <span className={`font-bold text-sm px-2 py-0.5 rounded-full ${pt.priority >= 4 ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                                        Priority: {pt.priority}/5
                                                    </span>
                                                </div>
                                                <p className="text-xs text-charcoal-light mt-1">{pt.reason}</p>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean, small?: boolean }> = ({ label, value, onChange, options, disabled, small }) => (
    <div>
        {label && <label className="block text-sm font-medium text-charcoal">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className={`mt-1 block w-full pl-3 pr-10 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md ${small ? 'py-1' : 'py-2'} disabled:bg-slate-100`}>
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default QBankGenerator;

import { GoogleGenAI, GenerateContentResponse, Chat, Type } from "@google/genai";
import { syllabus } from "../data/syllabus";
import { Question, PriorityTopic } from "../types";

// Ensure the API key is available. In a real app, this would be handled more robustly.
const API_KEY = process.env.API_KEY;
if (!API_KEY) {
  throw new Error("API_KEY environment variable not set.");
}
const ai = new GoogleGenAI({ apiKey: API_KEY });

const qBankModel = 'gemini-3-pro-preview';
const studyNotesModel = 'gemini-3-pro-preview';
const chatModel = 'gemini-3-flash-preview';
const BATCH_SIZE = 20; // Max questions per single API call to avoid constraint errors

/**
 * Generates a single batch of questions. This function is called internally by the main generateQuestions orchestrator.
 */
const generateQuestionBatch = async (exam: string, subject: string, topic: string, numQuestions: number): Promise<Question[]> => {
  const prompt = `
    You are an expert content creator for Indian competitive exams.
    **Instructions:**
    1.  Generate **exactly** ${numQuestions} diverse, high-quality, and unique questions (MCQ, Fill in the Blanks, True/False) for the chapter "${topic}" under the subject "${subject}" for the "${exam}" exam.
    2.  Ensure the questions are distinct from each other and cover different aspects of the chapter.
    3.  **Use Notation:** Where necessary, use LaTeX-style syntax within dollar signs for formulas, equations, and units (e.g., $H_2O$, $x^2$, $10^{-19} C$). Do NOT use markdown backticks for math formulas.
    **Output Format:**
    Return a single JSON object with a key "questions" containing an array. Do not include any markdown formatting like \`\`\`json. The 'questions' array **MUST** have exactly ${numQuestions} items.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: qBankModel,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    questions: {
                        type: Type.ARRAY,
                        minItems: numQuestions,
                        maxItems: numQuestions,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                questionText: { type: Type.STRING },
                                type: { type: Type.STRING, enum: ['MCQ', 'FillInTheBlank', 'TrueFalse', 'ShortAnswer'] },
                                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                                correctAnswer: { type: Type.STRING },
                                explanation: { type: Type.STRING },
                                difficulty: { type: Type.STRING, enum: ['Easy', 'Medium', 'Hard'] },
                                topic: { type: Type.STRING },
                            },
                             required: ['id', 'questionText', 'type', 'correctAnswer', 'explanation', 'difficulty', 'topic'],
                        },
                    },
                },
                 required: ['questions'],
            },
        },
    });

    const jsonText = response.text.trim();
    const data = JSON.parse(jsonText);
    return data.questions;
  } catch (error) {
    console.error(`Error generating a batch of ${numQuestions} questions:`, error);
    throw new Error(`Failed to generate a batch of questions from Gemini API.`);
  }
};

/**
 * Orchestrates the generation of questions, breaking large requests into smaller batches and executing them sequentially to avoid API rate limits.
 */
export const generateQuestions = async (exam: string, subject: string, topic: string, totalQuestions: number): Promise<Question[]> => {
  if (totalQuestions <= 0) {
    return [];
  }

  const numBatches = Math.ceil(totalQuestions / BATCH_SIZE);
  const allQuestions: Question[] = [];

  for (let i = 0; i < numBatches; i++) {
    const isLastBatch = i === numBatches - 1;
    const questionsInBatch = isLastBatch 
      ? totalQuestions - (i * BATCH_SIZE) 
      : BATCH_SIZE;

    if (questionsInBatch > 0) {
        try {
            // Await each batch sequentially to avoid rate limiting
            const batchResult = await generateQuestionBatch(exam, subject, topic, questionsInBatch);
            allQuestions.push(...batchResult);
        } catch (error) {
            console.error(`Error generating question batch ${i + 1} of ${numBatches}:`, error);
            throw new Error(`Failed to generate content from Gemini API. Batch ${i + 1} failed.`);
        }
    }
  }

  // The model might generate duplicate IDs across batches. Ensure they are unique.
  return allQuestions.map((q, index) => ({
      ...q,
      id: `${q.topic}-${index}`
  }));
};


export const getPriorityTopics = async (exam: string, subject: string): Promise<PriorityTopic[]> => {
  const chapterList = syllabus[exam]?.[subject] || [];
  if (chapterList.length === 0) {
    return [];
  }
  const prompt = `
    You are an expert analyst for Indian competitive exams.
    **Syllabus for ${subject} - ${exam}:**
    ${chapterList.join(', ')}

    **Instructions:**
    From the provided syllabus list, analyze all chapters for the subject "${subject}" and provide a prioritized list of the top 5 most important chapters. For each, give a priority score (1-5, 5 being highest) and a brief reason for its importance (e.g., "High weightage in past papers", "Fundamental concepts").

    **Output Format:**
    Return a single JSON object with a key "priorityTopics" containing an array of 5 items. Do not include any markdown formatting like \`\`\`json.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
        model: qBankModel,
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    priorityTopics: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                topic: { type: Type.STRING },
                                priority: { type: Type.NUMBER },
                                reason: { type: Type.STRING },
                            },
                            required: ['topic', 'priority', 'reason'],
                        },
                    },
                },
                required: ['priorityTopics'],
            },
        },
    });

    const jsonText = response.text.trim();
    const data = JSON.parse(jsonText);
    return data.priorityTopics;
  } catch (error) {
    console.error("Error getting priority topics:", error);
    throw new Error("Failed to get priority topics from Gemini API.");
  }
};


export const suggestVideo = async (topic: string, exam: string): Promise<string> => {
    const prompt = `Find a single, high-quality, and highly relevant YouTube video URL for a student preparing for the ${exam} exam on the topic: "${topic}". The video should be from a reputable educational channel. Return only the full YouTube URL and nothing else.`;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        return response.text;
    } catch (error) {
        console.error("Error suggesting video:", error);
        throw new Error("Failed to suggest a video.");
    }
};

export const generateStudyNotes = async (exam: string, subject: string, topic: string): Promise<string> => {
    const prompt = `
        Generate comprehensive, well-structured, and easy-to-understand study notes for a student preparing for the "${exam}" exam.
        Subject: "${subject}"
        Chapter: "${topic}"

        The notes should:
        - Be in Markdown format.
        - Focus specifically on the requested chapter.
        - Cover all key concepts clearly and in detail.
        - Use LaTeX-style syntax within dollar signs for formulas and equations (e.g., $E = mc^2$, $H_2O$).
        - Use headings, lists, and bold text for structure.
        - Include special markers for emphasis:
            - **[Key Concept]** for fundamental ideas.
            - **[Memorize this formula]** for important formulas.
            - **[Pro Tip]** for helpful exam-taking strategies or shortcuts.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        return response.text;
    } catch (error) {
        console.error("Error generating study notes:", error);
        throw new Error("Failed to generate study notes.");
    }
};

export const generateNotesForQuestion = async (question: Question, exam: string, subject: string): Promise<string> => {
    const prompt = `
        A student is preparing for the "${exam}" exam and is working on the subject "${subject}".
        They are currently attempting the following question on the chapter "${question.topic}":

        **Question:** "${question.questionText}"
        ${question.options ? `**Options:** ${question.options.join(', ')}` : ''}
        **Correct Answer:** ${question.correctAnswer}

        Generate concise and clear study notes in Markdown format that explain the key concepts, formulas, and principles required to understand and solve THIS SPECIFIC question.
        Focus only on the direct knowledge needed for this question. Do not explain the entire chapter.
        Use LaTeX-style syntax within dollar signs for any formulas or values (e.g., $H_2O$, $x^2$).
        Use headings, lists, and bold text. Mark important formulas with **[Memorize this formula]**.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
        });
        return response.text;
    } catch (error) {
        console.error("Error generating notes for question:", error);
        throw new Error("Failed to generate contextual notes.");
    }
};

export const createDoubtSolverChat = (): Chat => {
    const systemInstruction = `You are PrepAI, a super friendly, cheerful, and creative AI tutor for Indian students preparing for competitive exams like IIT JEE, NEET, and board exams. Your goal is to make learning fun and accessible.

    **Your Persona:**
    - **Tone:** Always use a positive, encouraging, and slightly informal tone.
    - **Emojis:** Use emojis generously to add personality and visual cues (e.g., 🧠, ✨, 👍, 🚀, 🤔, ✅).
    - **Formatting:** Use markdown (bold, italics, lists) to make explanations clear and engaging. For formulas, equations, and scientific notations, you MUST use LaTeX-style syntax within dollar signs (e.g., $H_2O$, $x^2$). Use markdown code blocks only for computer code snippets.
    - **Engagement:** Ask clarifying questions to better understand the student's doubt.

    **CRITICAL RULE: SYLLABUS BOUNDARY**
    You MUST ONLY answer questions related to the syllabus of:
    - **IIT JEE:** Physics, Chemistry, Maths
    - **NEET:** Physics, Chemistry, Biology
    - **Indian Board Exams (CBSE/ICSE):** Classes 10-12 subjects (Physics, Chemistry, Maths, Biology).

    If a student asks a question outside this scope (e.g., about history, geography, general knowledge, politics, or personal opinions), you MUST politely decline to answer the academic part. Instead, you MUST pivot to sharing a fun, unrelated science or math fact.

    **Example of Handling Out-of-Scope Question:**
    *Student:* "Who was the first Prime Minister of India?"
    *You:* "Oops! 😅 That's a great question, but it's a little outside my specialized circuits! I'm laser-focused on helping you ace Physics, Chemistry, Math, and Biology. But hey, speaking of amazing facts, did you know that the human brain generates about 12-25 watts of electricity? That's enough to power a low-wattage LED light bulb! 💡 How cool is that! Now, shall we get back to those tricky calculus problems? 🚀"
    `;

    return ai.chats.create({
        model: chatModel,
        config: {
            systemInstruction: systemInstruction,
        },
    });
};

