const studyNotesCache = new Map<string, string>();

export const generateStudyNotes = async (exam: string, subject: string, topic: string, subTopic?: string): Promise<string> => {
    const cacheKey = `${exam}-${subject}-${topic}-${subTopic || 'Entire Chapter'}`;
    if (studyNotesCache.has(cacheKey)) {
        return studyNotesCache.get(cacheKey)!;
    }

    const focus = subTopic && subTopic !== 'Entire Chapter' 
        ? `The notes must focus specifically on the sub-topic: "${subTopic}".`
        : `The notes should cover the entire chapter comprehensively.`;

    const prompt = `
        Generate comprehensive, well-structured, and easy-to-understand study notes for a student preparing for the "${exam}" exam.
        Subject: "${subject}"
        Chapter: "${topic}"

        **Focus Area:**
        ${focus}

        The notes should:
        - Be in Markdown format.
        - Cover all key concepts clearly and in detail for the specified focus area.
        - Use LaTeX-style syntax within dollar signs for formulas and equations (e.g., $E = mc^2$, $H_2O$).
        - Use headings, lists, and bold text for structure.
        - Include special markers for emphasis:
            - **[Key Concept]** for fundamental ideas.
            - **[Memorize this formula]** for important formulas.
            - **[Pro Tip]** for helpful exam-taking strategies or shortcuts.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: studyNotesModel,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });
        const notes = response.text;
        studyNotesCache.set(cacheKey, notes);
        return notes;
    } catch (error) {
        console.error("Error generating study notes:", error);
        throw new Error("Failed to generate study notes.");
    }
};

const questionNotesCache = new Map<string, string>();

