import React, { useState, useEffect, useCallback, useRef } from 'react';
import { syllabus } from '../data/syllabus';
import { generateStudyNotes, getSubTopics } from '../services/geminiService';
import MarkdownRenderer from '../components/ui/MarkdownRenderer';
import Loader from '../components/ui/Loader';
import { SparklesIcon, RefreshIcon } from '../components/icons/Icons';

interface StudyMaterialsProps {
    initialContext?: {
        exam: string;
        subject: string;
        topic: string;
    } | null;
}

const StudyMaterials: React.FC<StudyMaterialsProps> = ({ initialContext }) => {
    const [exam, setExam] = useState(initialContext?.exam || Object.keys(syllabus)[0]);
    const [subject, setSubject] = useState(initialContext?.subject || '');
    const [topic, setTopic] = useState(initialContext?.topic || '');
    const [subTopic, setSubTopic] = useState('Entire Chapter');

    const [subjects, setSubjects] = useState<string[]>([]);
    const [topics, setTopics] = useState<string[]>([]);
    const [subTopics, setSubTopics] = useState<string[]>(['Entire Chapter']);

    const [notes, setNotes] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isLoadingSubTopics, setIsLoadingSubTopics] = useState(false);
    const [error, setError] = useState('');
    const initialFetchDone = useRef(false);

    useEffect(() => {
        const availableSubjects = Object.keys(syllabus[exam] || {});
        setSubjects(availableSubjects);
        if (!initialContext || exam !== initialContext.exam) {
            setSubject(availableSubjects[0] || '');
        }
    }, [exam, initialContext]);

    useEffect(() => {
        if (subject) {
            const availableTopics = syllabus[exam]?.[subject] || [];
            setTopics(availableTopics);
            if (!initialContext || subject !== initialContext.subject) {
                setTopic(availableTopics[0] || '');
            }
        } else {
            setTopics([]);
            setTopic('');
        }
    }, [exam, subject, initialContext]);

    const handleGetNotes = useCallback(async () => {
        if (!exam || !subject || !topic) {
            setError('Please select all fields.');
            return;
        }
        setIsLoading(true);
        setError('');
        setNotes('');
        try {
            const result = await generateStudyNotes(exam, subject, topic, subTopic);
            setNotes(result);
        } catch (err) {
            setError('Failed to generate study notes. Please try again.');
            console.error(err);
        }
        setIsLoading(false);
    }, [exam, subject, topic, subTopic]);

    useEffect(() => {
        if (initialContext && !initialFetchDone.current) {
            initialFetchDone.current = true;
            handleGetNotes();
        }
    }, [initialContext, handleGetNotes]);

    useEffect(() => {
        setSubTopic('Entire Chapter');
        setSubTopics(['Entire Chapter']);
        if (!topic) return;

        const handler = setTimeout(() => {
            const fetchSubTopics = async () => {
                if (exam && subject && topic) {
                    setIsLoadingSubTopics(true);
                    try {
                        const subTopicsResult = await getSubTopics(exam, subject, topic);
                        setSubTopics(['Entire Chapter', ...subTopicsResult]);
                    } catch (err) {
                        console.error("Failed to fetch sub-topics:", err);
                        setSubTopics(['Entire Chapter']);
                    } finally {
                        setIsLoadingSubTopics(false);
                    }
                }
            };
            fetchSubTopics();
        }, 500);

        return () => clearTimeout(handler);
    }, [exam, subject, topic]);

    const handleReset = () => {
        setNotes('');
        setError('');
        setExam(Object.keys(syllabus)[0]);
        // The useEffects will handle resetting the subject and topic based on the new exam.
        setSubTopic('Entire Chapter');
        initialFetchDone.current = false; // Reset for potential new initial contexts
    };


    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-md border border-slate-200">
                <h2 className="text-2xl font-bold font-serif text-charcoal mb-4">Study Materials</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
                    <SelectControl label="Exam" value={exam} onChange={e => setExam(e.target.value)} options={Object.keys(syllabus)} />
                    <SelectControl label="Subject" value={subject} onChange={e => setSubject(e.target.value)} options={subjects} disabled={!exam} />
                    <SelectControl label="Chapter" value={topic} onChange={e => setTopic(e.target.value)} options={topics} disabled={!subject} />
                    <SelectControl label="Sub-Topic" value={subTopic} onChange={e => setSubTopic(e.target.value)} options={subTopics} disabled={isLoadingSubTopics || !topic} />
                </div>
                <div className="mt-6 flex justify-end gap-x-4">
                    <button onClick={handleReset} className="flex items-center justify-center bg-slate-200 text-charcoal font-bold py-2 px-6 rounded-lg shadow-sm hover:bg-slate-300 transition-colors">
                        <RefreshIcon className="mr-2 h-5 w-5"/> Reset
                    </button>
                    <button onClick={handleGetNotes} disabled={isLoading} className="flex items-center justify-center bg-accent text-white font-bold py-2 px-6 rounded-lg shadow-sm hover:bg-accent-600 transition-colors disabled:bg-slate-400">
                        {isLoading ? <><Loader size="sm" /> Generating...</> : <><SparklesIcon /> Get Notes</>}
                    </button>
                </div>
                {error && <p className="text-red-500 mt-4">{error}</p>}
            </div>

            {isLoading && (
                <div className="bg-white p-6 rounded-xl shadow-md border border-slate-200 text-center">
                    <Loader />
                    <p className="mt-4 text-charcoal-light">Our AI is crafting the perfect notes for you...</p>
                </div>
            )}

            {notes && !isLoading && (
                <div className="bg-white p-8 rounded-xl shadow-md border border-slate-200">
                    <h3 className="text-2xl font-bold font-serif text-charcoal mb-4 border-b-2 border-slate-200 pb-2">Notes for: {topic} {subTopic !== 'Entire Chapter' && ` - ${subTopic}`}</h3>
                    <MarkdownRenderer content={notes} />
                </div>
            )}
        </div>
    );
};

const SelectControl: React.FC<{ label?: string, value: string, onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void, options: string[], disabled?: boolean }> = ({ label, value, onChange, options, disabled }) => (
    <div>
        {label && <label className="block text-sm font-medium text-charcoal">{label}</label>}
        <select value={value} onChange={onChange} disabled={disabled} className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md disabled:bg-slate-100">
            {options.length === 0 && <option>None</option>}
            {options.map(opt => <option key={opt} value={opt}>{opt}</option>)}
        </select>
    </div>
);

export default StudyMaterials;

